import Kategory from "./components/sidebar/kategory.jsx";
import Top from './components/content/top';

// import HeaderSearch from './components/search/headerSearch.jsx';




 const App = ()=> {
     return  (
     <>
     <div><Header/></div>
   {/* <div><HeaderSearch/></div> */}
     <div><Top/></div>
      <div> <Sidebar /><Kategory></Kategory></div>



      </>
     )
 }

ReactDOM.render(<Header></Header>, document.querySelector('#header'));
// ReactDOM.render(<HeaderSearch></HeaderSearch>, document.querySelector('.search'));
ReactDOM.render(<Sidebar></Sidebar>, document.querySelector('#sidebar'));
ReactDOM.render(<Top></Top>, document.querySelector('#top'));

export default App;
